// Nth most frequent character:
String str = "AABABCCC";
// A=3, B=2, C=3  ← A and C TIE at count 3!

Map<Character, Long> freq = str.chars().mapToObj(c -> (char) c)
    .collect(Collectors.groupingBy(Function.identity(),
        LinkedHashMap::new, Collectors.counting()));
// LinkedHashMap: {A=3, B=2, C=3}  ← A before C (appeared first)

// Most frequent: sorted desc → A(3), C(3), B(2). findFirst → A (tie-break: appeared first)
// 2nd most frequent: skip(1) → C(3) (same count as A, but second in insertion order)
// 3rd most frequent: skip(2) → B(2)

// With HashMap: {A=3, B=2, C=3} or {C=3, A=3, B=2} — random! Tie-break is unpredictable.
