package com.bank.pattern.service;

import com.bank.pattern.dto.FrequencyResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
@Slf4j
public class FrequencyService {

    public FrequencyResult findNthMostFrequent(String input, int n) {

        // Step 1: frequency map with LinkedHashMap (insertion order for tie-break)
        Map<Character, Long> freq = input.chars()
            .mapToObj(c -> (char) c)
            .collect(Collectors.groupingBy(
                Function.identity(),
                LinkedHashMap::new,
                Collectors.counting()));

        // Step 2: sort by value descending, then by insertion order (LinkedHashMap)
        List<Map.Entry<Character, Long>> ranked = freq.entrySet().stream()
            .sorted(Map.Entry.<Character, Long>comparingByValue().reversed())
            .toList();

        // Step 3: get Nth entry (skip n-1)
        Optional<Map.Entry<Character, Long>> nthEntry = ranked.stream()
            .skip((long) n - 1)
            .findFirst();

        // Ranked display
        List<String> rankedDisplay = new ArrayList<>();
        for (int i = 0; i < ranked.size(); i++) {
            var entry = ranked.get(i);
            rankedDisplay.add("#" + (i + 1) + " '" + entry.getKey() + "' (count=" + entry.getValue() + ")");
        }

        // Detect ties
        String tieExplanation = "No ties";
        if (ranked.size() >= 2) {
            long firstCount = ranked.get(0).getValue();
            long tiedWithFirst = ranked.stream().filter(e -> e.getValue() == firstCount).count();
            if (tiedWithFirst > 1) {
                tieExplanation = tiedWithFirst + " characters tied at count " + firstCount
                    + ". LinkedHashMap breaks tie by insertion order (first-seen-in-string wins).";
            }
        }

        return new FrequencyResult(input, n,
            nthEntry.map(Map.Entry::getKey).orElse(null),
            nthEntry.map(Map.Entry::getValue).orElse(null),
            rankedDisplay, freq, tieExplanation);
    }
}
