package com.bank.pattern.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class NthMostFrequentTest {

    private Optional<Character> nthMostFrequent(String s, int n) {
        return s.chars().mapToObj(c -> (char) c)
            .collect(Collectors.groupingBy(Function.identity(),
                LinkedHashMap::new, Collectors.counting()))
            .entrySet().stream()
            .sorted(Map.Entry.<Character, Long>comparingByValue().reversed())
            .skip(n - 1)
            .findFirst()
            .map(Map.Entry::getKey);
    }

    @Test
    void mostFrequent() {
        assertThat(nthMostFrequent("AABABCCC", 1)).contains('A'); // A=3, tie with C=3, A first
    }

    @Test
    void secondMostFrequent() {
        assertThat(nthMostFrequent("AABABCCC", 2)).contains('C'); // C=3, tied with A but second
    }

    @Test
    void thirdMostFrequent() {
        assertThat(nthMostFrequent("AABABCCC", 3)).contains('B'); // B=2
    }

    @Test
    void nBeyondRange() {
        assertThat(nthMostFrequent("ABC", 10)).isEmpty();
    }

    @Test
    void tieBreakByInsertionOrder() {
        // "XYX" → X=2, Y=1. Most frequent = X
        assertThat(nthMostFrequent("XYX", 1)).contains('X');

        // "XYXY" → X=2, Y=2. Tie! LinkedHashMap: X appeared first → X wins
        assertThat(nthMostFrequent("XYXY", 1)).contains('X');
        assertThat(nthMostFrequent("YXYX", 1)).contains('Y'); // Y appeared first here
    }

    @Test
    void singleCharRepeated() {
        assertThat(nthMostFrequent("AAAA", 1)).contains('A');
        assertThat(nthMostFrequent("AAAA", 2)).isEmpty(); // only 1 distinct char
    }
}
